+                     */
+                    nstime_t ns;
+                    uint64_t resp_time;
+                    nstime_delta(&ns, &pinfo->abs_ts, &ual->ts );
+                    resp_time = ns.nsecs + ns.secs*NANOSECS_PER_SEC;
