+                                    i++;
+                                }
+
+                                /* fine, it's probably a Fast Retrans triggered by the SACK sender algo */
+                                if(!is_sacked) {
+                                    if(!tcpd->ta)
+                                        tcp_analyze_get_acked_struct(pinfo->num, seq, ack, true, tcpd);
